        heading: '१. सिमाना र साँधियार विवादका मुख्य कारणहरू',
        content: `नेपालमा जग्गासम्बन्धी विवादहरूमध्ये करिब ७० प्रतिशत विवाद साँधियारसँग सिमाना मिचिएको, बाटो छेकेको वा पर्खाल लगाउँदा जग्गा घटेको विषयमा हुने गर्छन्। पुरानो स्केलको नापी नक्सा (१:२५०० वा १:१२५०), फिल्डमा सिमाना चिन्ह (किला) नगाडिनु, प्लटिङ गर्दा नापी अमिन बिना जथाभावी बाँडिनु र खोला/पैनीले धार परिवर्तन गर्नु यसका प्रमुख कारणहरू हुन्।`,
