        heading: '१. नापजाँच तथा सर्भे सिद्धान्त',
        content: `**प्र. १: सर्भेको मुख्य आधारभूत सिद्धान्त के हो?**
**उत्तर:** सर्भेको मुख्य सिद्धान्त 'Whole to Part' (पूर्णबाट अंशतिर काम गर्ने) हो। यसले गर्दा त्रुटिहरू (Errors) एक ठाउँबाट अर्को ठाउँमा जम्मा (Accumulate) हुन पाउँदैनन्।

**प्र. २: नेपालको क्याडस्ट्रल सर्भेमा कुन प्रोजेक्सन प्रणाली प्रयोग गरिन्छ?**
**उत्तर:** नेपालमा Modified Universal Transverse Mercator (MUTM) प्रोजेक्सन प्रणाली (८१°, ८४° र ८७° सेन्ट्रल मेरिडियन) प्रयोग गरिन्छ।

**प्र. ३: क्याडस्ट्रल नक्सा (Cadastral Map) कुन स्केलमा तयार गरिन्छ?**
**उत्तर:** नेपालमा जनघनत्व अनुसार १:५००, १:१२५०, १:२५०० र ग्रामीण भेगमा १:४८०० स्केलमा कित्ता नक्सा तयार गरिन्छ।`,
