        content: `**प्र. ४: गन्टर चेन (Gunter's Chain) को लम्बाइ कति हुन्छ?**
**उत्तर:** गन्टर चेनको लम्बाइ ६६ फिट (१०० कडी/Links) हुन्छ।

**प्र. ५: प्लेन टेबल सर्भे गर्दा कुन सिद्धान्त अपनाइन्छ?**
**उत्तर:** समानान्तरता (Parallelism) को सिद्धान्त।

**प्र. ६: त्रि-कोणमितिमा ३ विन्दु समस्या (Three Point Problem) समाधान गर्ने विधिहरू के-के हुन्?**
**उत्तर:** मेकानिकल (ट्रेसिङ पेपर) विधि, ग्राफिकल (बेसेल) विधि, र लेहम्यान्स (Trial and Error) विधि।`,
