        content: `**प्र. ७: बेन्चमार्क (Bench Mark - BM) भनेको के हो?**
**उत्तर:** समुन्द्र सतहबाट उचाइ (Reduced Level) पहिले नै यकिन गरिएको स्थायी सन्दर्भ बिन्दुलाई बेन्चमार्क भनिन्छ।

**प्र. ८: कन्टुर रेखा (Contour Line) ले के जनाउँछ?**
**उत्तर:** जमिनको सतहमा समान उचाइ (Equal Elevation) भएका बिन्दुहरूलाई जोड्ने काल्पनिक रेखालाई कन्टुर भनिन्छ। दुई कन्टुर रेखा एकआपसमा कहिल्यै काटिँदैनन् (अपवाद: ओभरह्याङ्गिङ क्लिफ बाहेक)।`,
