    {
      id: "sec-valuation-formula",
      heading: "२. बैंक इन्जिनियरले गर्ने जग्गाको मूल्याङ्कन सूत्र (FMV & Distress Value)",
      content: "बैंकले जग्गाको मूल्याङ्कन गर्दा ऋणीले भनेको भाउ वा बजारमा चलेको भाउ सिधै मान्दैन। यसका लागि नेपाल इन्जिनियरिङ काउन्सिलमा दर्ता भएका आधिकारिक बैंक भ्यालुएटर (Bank Valuator Engineer) ले स्थलगत निरीक्षण (Field Inspection) गरी वैज्ञानिक सूत्र अनुसार मूल्याङ्कन प्रतिवेदन (Valuation Report) तयार गर्छन्।\n\nबैंक मूल्याङ्कन निकाल्ने मुख्य सूत्र:\n१. सरकारी न्यूनतम मूल्याङ्कन (Government Valuation): जिल्ला मालपोत कार्यालयले रजिष्ट्रेसन प्रयोजनका लागि तोकेको दररेट।\n२. प्रचलित बजार मूल्य (Market Value): स्थानीय स्तरमा खरिदबिक्री भइरहेको वास्तविक कारोबार दर।\n३. भारित औसत मूल्याङ्कन (Fair Market Value - FMV):\nबैंकहरूले सामान्यतया बजार मूल्यको ६०% देखि ७०% र सरकारी मूल्याङ्कनको ३०% देखि ४०% जोडेर औसत फेयर मार्केट भ्यालु निकाल्छन्।\nसूत्र: FMV = (बजार मूल्य × ०.७०) + (सरकारी दर × ०.३०)\n\n४. संकटकालीन बिक्री मूल्य (Distress Value / Force Sale Value):\nयदि ऋणीले ऋण तिर्न नसकेर बैंकले लिलामी (Auction) गर्नुपरेमा तुरुन्तै बिक्री हुनसक्ने अनुमानित मूल्यलाई डिस्ट्रेस भ्यालु भनिन्छ। यो सामान्यतया FMV को ७०% देखि ८०% बराबर हुन्छ। बैंकले ऋण स्वीकृत गर्दा यही Distress Value लाई मुख्य आधार मान्ने गर्छ।",
      alert: {
        type: "info",
        title: "नापी प्राविधिक सल्लाह",
        text: "जग्गाको मोहोडा (Frontage) राम्रो भएको, बाटो चौडा भएको र चारैतिर पक्की सिमाना भएको जग्गाको बजार मूल्य इन्जिनियरले बढी लगाइदिन्छन्। बाङ्गो वा त्रिकोणात्मक जग्गाको डिस्ट्रेस भ्यालु कम निस्कन्छ।"
      }
    },
    {
      id: "sec-rejected-land",
      heading: "३. कस्तो जग्गामा बैंकले एक रुपैयाँ पनि ऋण दिँदैन? (५ मुख्य कारण)",
      content: "धेरै जग्गाधनीहरू आफ्नो नाममा लालपुर्जा हुँदाहुँदै पनि बैंकले ऋण अस्वीकार (Reject) गरिदिएको गुनासो गर्छन्। नेपालका बैंक तथा वित्तीय संस्थाहरूले निम्न ५ प्रकारका जग्गाहरूलाई कालोसूचीमा राखी धितो स्वीकार गर्दैनन्:\n\n१. मोटरबाटो नपुगेको वा मापदण्ड नपुगेको जग्गा:\nयदि जग्गासम्म पुग्ने बाटो नापी नक्सामा स्पष्ट छैन वा बाटोको चौडाइ न्यूनतम ८ फिट (काठमाडौंमा १० देखि १३ फिट) भन्दा कम छ भने बैंकले सिधै फाइल अस्वीकार गर्छ। गोरेटो बाटो मात्र भएको जग्गा बैंकमा धितो बस्दैन।\n\n२. बिजुलीको हाइटेन्सन (High Tension) ट्रान्समिसन लाइन मुनिको जग्गा:\nनेपाल विद्युत प्राधिकरण (NEA) को ६६kV, १३२kV वा २२०kV को प्रसारण लाइनको तार मुनि पर्ने जग्गामा कुनै पनि बैंकले कर्जा लगानी गर्दैन।\n\n३. खोला, नदी वा खोल्साको राइट-अफ-वे (Setback) भित्र परेको जग्गा:\nकाठमाडौं उपत्यकाका बागमती, विष्णुमती, धोबीखोला वा देशका अन्य प्रमुख नदी किनारबाट २० मिटर मापदण्ड भित्र पर्ने जग्गामा निर्माण स्वीकृति नपाइने हुनाले बैंकले धितो लिन मान्दैन।\n\n४. सार्वजनिक, वन वा सरकारी सिमाना विवाद भएको जग्गा:\nजग्गाको सिमाना सरकारी जग्गा, सार्वजनिक ऐलानी, पर्ती वा वन क्षेत्रसँग जोडिएको छ र साँधियारसँग विवाद छ भने बैंकको कानुनी सल्लाहकार (Legal Advisor) ले ऋण रोक्का गर्छ।\n\n५. कृषि क्षेत्रमा मात्र वर्गीकरण भएको तर आवासीय कारोबार गर्न खोजिएको जग्गा:\nभूउपयोग ऐन २०७९ अनुसार स्थानीय तहले कृषि क्षेत्र तोकेको र कित्ताकाट वा बिक्री गर्न नमिल्ने गरी बन्देज भएको जग्गामा धितो कर्जा स्वीकृत हुँदैन।",
      alert: {
        type: "warning",
        title: "गम्भीर चेतावनी",
        text: "जग्गाको लालपुर्जामा कित्ता नम्बर भए पनि नापी नक्सा (Cadastral Blueprint) मा बाटो स्पष्ट कोरिएको छैन भने बैंक भ्यालुएटरले नेगेटिभ रिपोर्ट लेखिदिन्छ। त्यसैले लोन हाल्नुअघि वडाबाट बाटो प्रमाणित सिफारिस लिनुहोस्।"
      }
    },
    {
      id: "sec-required-docs",
      heading: "४. बैंक लोनका लागि आवश्यक पर्ने सम्पूर्ण आधिकारिक कागजातहरूको चेकलिस्ट",
      content: "जग्गा धितो राखी बैंकबाट छिटो र झन्झटमुक्त कर्जा स्वीकृत गराउन निम्न कागजातहरूको सक्कल र प्रमाणित प्रतिलिपि तयार राख्नुपर्छ:\n\n१. जग्गाधनी प्रमाणपुर्जा (लालपुर्जा) को प्रमाणित प्रतिलिपि।\n२. नापी कार्यालयबाट हालसालै जारी भएको प्रमाणित ब्लुप्रिन्ट नक्सा र ट्रेस नक्सा।\n३. सम्बन्धित वडा कार्यालयले जारी गरेको आधिकारिक 'चारकिल्ला प्रमाणित' सिफारिस पत्र।\n४. चालु आर्थिक वर्षको सम्पत्ति कर तथा मालपोत तिरो तिरेको सक्कल रसिद।\n५. जग्गाधनी, ऋणी र धितोकर्ताको नागरिकताको प्रतिलिपि तथा २/२ प्रति पासपोर्ट साइज फोटो।\n६. पारिवारिक विवरण (तीन पुस्ते विवरण) खुल्ने स्थानीय तहको नाता प्रमाणित कागजात।\n७. घर भएमा: नगरपालिकाबाट स्वीकृत नक्सा पास प्रमाणपत्र, निर्माण इजाजत, र निर्माण सम्पन्न प्रमाणपत्र।\n८. आम्दानीको स्रोत: तलब प्रमाणपत्र, व्यवसाय दर्ता (PAN/VAT दर्ता, अडिट रिपोर्ट, कर चुक्ता), वा घरबहाल सम्झौता पत्र।\n९. बैंकबाट धितो स्वीकृत भएपछि सम्बन्धित मालपोत कार्यालयबाट जारी हुने आधिकारिक 'धितो रोक्का पत्र' (Mortgage Freeze Slip)।"
    }
