      id: "sec-nepal-endorsement",
      heading: "३. नेपालको कन्सुलर विभाग र मालपोत कार्यालयमा अभिलेखीकरण गर्ने तरिका",
      content: "दूतावासबाट प्रमाणित भएको वारेसनामा पत्र नेपाल आइपुगेपछि तुरुन्तै मालपोतमा काम हुँदैन। नेपालमा निम्न २ वटा थप सरकारी प्रक्रिया पूरा गर्नुपर्छ:\n\n१. परराष्ट्र मन्त्रालय कन्सुलर सेवा विभाग (त्रिपुरेश्वर, काठमाडौं):\nदूतावासको छाप र हस्ताक्षर सक्कल हो भनी कन्सुलर सेवा विभागबाट आधिकारिक प्रमाणीकरण (Endorsement / Verification Stamp) गराउनुपर्छ। यसका लागि नेपालको कन्सुलर विभागमा अनलाइन फारम भरी सक्कल कागजात पेस गर्नुपर्छ।\n\n२. सम्बन्धित जिल्लाको मालपोत कार्यालयमा अभिलेख:\nकन्सुलर विभागले छाप लगाइदिएपछि वारेस पाउने व्यक्तिले सम्बन्धित मालपोत कार्यालयमा गएर वारेसनामा दर्ता (POA Registration) गराउनुपर्छ। मालपोत अधिकृतले वारेसनामाको वैधता परीक्षण गरी आधिकारिक अभिलेख किताबमा चढाएपछि मात्र जग्गा खरिद, बिक्री वा रोक्का गर्ने कानुनी अधिकार प्राप्त हुन्छ।",
